import math
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# -------------------- CUDA extension --------------------
src = r'''
#include <torch/extension.h>
#include <cuda_fp16.h>

template <typename scalar_t>
__global__ void conv2d_fp16_kernel(const __half* __restrict__ input,
                                   const __half* __restrict__ weight,
                                   const __half* __restrict__ bias,
                                   __half* __restrict__ output,
                                   int N, int C, int H, int W,
                                   int outC, int K, int stride, int padding,
                                   int outH, int outW) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = N * outC * outH * outW;
    if (idx >= total) return;

    // decode indices
    int ow = idx % outW;
    int tmp = idx / outW;
    int oh = tmp % outH;
    tmp = tmp / outH;
    int oc = tmp % outC;
    int n  = tmp / outC;

    float acc = 0.0f;
    for (int ic = 0; ic < C; ++ic) {
        for (int kh = 0; kh < K; ++kh) {
            int ih = -padding + oh * stride + kh;
            if (ih < 0 || ih >= H) continue;
            for (int kw = 0; kw < K; ++kw) {
                int iw = -padding + ow * stride + kw;
                if (iw < 0 || iw >= W) continue;
                int input_idx = ((n * C + ic) * H + ih) * W + iw;
                int weight_idx = ((oc * C + ic) * K + kh) * K + kw;
                __half h_in = input[input_idx];
                __half h_wt = weight[weight_idx];
                acc += __half2float(h_in) * __half2float(h_wt);
            }
        }
    }
    // add bias
    acc += __half2float(bias[oc]);
    output[idx] = __float2half(acc);
}

void conv2d_fp16(at::Tensor input,
                 at::Tensor weight,
                 at::Tensor bias,
                 at::Tensor output,
                 int stride,
                 int padding) {
    const int N   = input.size(0);
    const int C   = input.size(1);
    const int H   = input.size(2);
    const int W   = input.size(3);
    const int outC= weight.size(0);
    const int K   = weight.size(2); // assume square kernel
    const int outH= output.size(2);
    const int outW= output.size(3);

    const int total = N * outC * outH * outW;
    const int threads = 256;
    const int blocks = (total + threads - 1) / threads;

    conv2d_fp16_kernel<<<blocks, threads>>>(
        reinterpret_cast<const __half*>(input.data_ptr<at::Half>()),
        reinterpret_cast<const __half*>(weight.data_ptr<at::Half>()),
        reinterpret_cast<const __half*>(bias.data_ptr<at::Half>()),
        reinterpret_cast<__half*>(output.data_ptr<at::Half>()),
        N, C, H, W,
        outC, K, stride, padding,
        outH, outW);

    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        printf("CUDA error in conv2d_fp16: %s\\n", cudaGetErrorString(err));
    }
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("conv2d_fp16", &conv2d_fp16, "FP16 Conv2d forward (CUDA)");
}
'''

conv2d_gpu = load_inline(name='conv2d_gpu',
                         cpp_sources=[src],
                         functions=['conv2d_fp16'],
                         verbose=False)

# -------------------- Model definition --------------------
class ModelNew(nn.Module):
    def __init__(self, num_classes=1000):
        super(ModelNew, self).__init__()
        self.in_channels = 3
        self.out_channels = 96
        self.kernel_size = 11
        self.stride = 4
        self.padding = 2

        self.weight = nn.Parameter(
            torch.empty(self.out_channels,
                        self.in_channels,
                        self.kernel_size,
                        self.kernel_size,
                        dtype=torch.float16,
                        device='cuda')
        )
        self.bias = nn.Parameter(
            torch.empty(self.out_channels,
                        dtype=torch.float16,
                        device='cuda')
        )
        # Initialize like nn.Conv2d
        nn.init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        fan_in, _ = nn.init._calculate_fan_in_and_fan_out(self.weight)
        bound = 1 / math.sqrt(fan_in)
        nn.init.uniform_(self.bias, -bound, bound)

    def forward(self, x):
        # ensure input is fp16, contiguous, on CUDA
        x = x.to(dtype=torch.float16, device='cuda')
        x = x.contiguous()

        N, _, H, W = x.shape
        out_h = (H + 2 * self.padding - self.kernel_size) // self.stride + 1
        out_w = (W + 2 * self.padding - self.kernel_size) // self.stride + 1

        out = torch.empty(N,
                          self.out_channels,
                          out_h,
                          out_w,
                          dtype=torch.float16,
                          device='cuda')
        conv2d_gpu.conv2d_fp16(x, self.weight, self.bias, out,
                               self.stride, self.padding)
        return out
